/**
 * Libros de hechizos: build words by joining a beginning piece and an ending piece, colour-coded by family.
 * - sílabas: two-syllable words of open syllables (ma + sa -> mesa? no: me + sa), families by consonant;
 * - sufijos: word-bank words with -ción, -dad, -ero, -ería, and adverbs in -mente made from bank adjectives;
 * - verbos: regular verb stems + endings, generated by the conjugation engine for one tense.
 * Pure (tested).
 */
import { conjugate, PERSONS, type Conjugation } from '../../lang/es/conjugate.ts';
import { syllabify } from '../../lang/es/syllabify.ts';
import type { WordEntry } from '../../words/types.ts';
import { levelRank, rng, shuffle } from '../kit/answer.ts';

export type ModeId = 'silabas' | 'sufijos' | 'presente' | 'indefinido' | 'imperfecto' | 'futuro' | 'subjuntivo' | 'subjuntivo-imperfecto';
type TenseKey = { mood: 'indicative' | 'subjunctive'; tense: string };
export const TENSES: Partial<Record<ModeId, TenseKey & { name: string }>> = {
  presente: { mood: 'indicative', tense: 'presente', name: 'presente' },
  indefinido: { mood: 'indicative', tense: 'preterito', name: 'pretérito indefinido' },
  imperfecto: { mood: 'indicative', tense: 'imperfecto', name: 'pretérito imperfecto' },
  futuro: { mood: 'indicative', tense: 'futuro', name: 'futuro' },
  subjuntivo: { mood: 'subjunctive', tense: 'presente', name: 'presente de subjuntivo' },
  'subjuntivo-imperfecto': { mood: 'subjunctive', tense: 'imperfecto', name: 'imperfecto de subjuntivo' },
};
export const MODES: { id: ModeId; level: string; maxLevel: string }[] = [
  { id: 'silabas', level: 'A1', maxLevel: 'A2' },
  { id: 'presente', level: 'A1', maxLevel: 'A1' },
  { id: 'sufijos', level: 'A2–B2', maxLevel: 'B2' },
  { id: 'indefinido', level: 'A2', maxLevel: 'A2' },
  { id: 'imperfecto', level: 'A2', maxLevel: 'A2' },
  { id: 'futuro', level: 'B1', maxLevel: 'B1' },
  { id: 'subjuntivo', level: 'B2', maxLevel: 'B2' },
  { id: 'subjuntivo-imperfecto', level: 'C1', maxLevel: 'C1' },
];

export interface Piece { id: string; text: string; family: number; role: 'start' | 'end' }
export interface Target { word: string; start: string; end: string; family: number; /** hint shown before it is found */ hint: { en: string; ru: string } | string }
export interface Page { mode: ModeId; targets: Target[]; starts: Piece[]; ends: Piece[]; families: string[]; /** every word a join may make (targets and extras) */ valid: Map<string, string> }

const OPEN = /^(ch|ll|[bcdfgjlmnñprstvz])[aeiouáéíóú]$/;
/** Two-syllable words made of two open syllables (casa, mesa, luna, mamá). */
export function syllableWords(words: WordEntry[], maxLevel: string): { e: WordEntry; s: [string, string] }[] {
  const out: { e: WordEntry; s: [string, string] }[] = [];
  const seen = new Set<string>();
  for (const e of words) {
    if (levelRank(e.level) > levelRank(maxLevel) || e.pos === 'expression' || !/^[a-záéíóúñ]+$/.test(e.lemma) || seen.has(e.lemma)) continue;
    const s = syllabify(e.lemma);
    if (s.length === 2 && OPEN.test(s[0]) && OPEN.test(s[1])) { out.push({ e, s: [s[0], s[1]] }); seen.add(e.lemma); }
  }
  return out;
}
const consonant = (syl: string) => syl.replace(/[aeiouáéíóú]$/, '');

export const SUFFIXES = ['ción', 'dad', 'ero', 'ería', 'mente'] as const;
/** Adjectives whose -mente adverb is common: the feminine form + mente. */
const MENTE_OK = ['rápido', 'lento', 'fácil', 'tranquilo', 'claro', 'feliz', 'normal', 'final', 'real', 'total', 'sincero', 'perfecto', 'exacto', 'amable', 'alegre', 'triste', 'tranquilo', 'cariñoso', 'general', 'seguro', 'libre', 'reciente', 'directo', 'serio', 'difícil', 'cómodo', 'tajante', 'escueto', 'exhaustivo', 'minucioso', 'somero'];
const NOT_SUFFIX = new Set(['ciudad', 'febrero', 'entero', 'cero', 'ligero', 'sincero', 'verdadero', 'soltero', 'tablero']);
/** Bank words that end in a suffix (stem of 3+ letters without its own accent), and -mente adverbs. */
export function suffixWords(words: WordEntry[], maxLevel: string): { word: string; stem: string; suffix: string; e: WordEntry }[] {
  const out: { word: string; stem: string; suffix: string; e: WordEntry }[] = [];
  const seen = new Set<string>();
  for (const e of words) {
    if (levelRank(e.level) > levelRank(maxLevel) || !/^[a-záéíóúñ]+$/.test(e.lemma) || seen.has(e.lemma) || NOT_SUFFIX.has(e.lemma)) continue;
    if (e.pos === 'adjective' && MENTE_OK.includes(e.lemma)) {
      const fem = e.lemma.endsWith('o') ? `${e.lemma.slice(0, -1)}a` : e.lemma;
      out.push({ word: `${fem}mente`, stem: fem, suffix: 'mente', e });
    }
    if (e.pos !== 'noun') continue;
    const suf = [...SUFFIXES].sort((a, b) => b.length - a.length).find((s) => s !== 'mente' && e.lemma.endsWith(s));
    if (!suf) continue;
    const stem = e.lemma.slice(0, -suf.length);
    if (stem.length < 3 || /[áéíóú]/.test(stem)) continue;
    out.push({ word: e.lemma, stem, suffix: suf, e });
    seen.add(e.lemma);
  }
  return out;
}

/** Regular verbs of a level (no reflexives) and the stem + ending split of each form of a tense. */
export function verbForms(e: WordEntry, tk: TenseKey): { verb: string; stem: string; forms: { person: number; form: string; end: string }[]; cls: string } | null {
  if (e.pos !== 'verb' || e.verbModel !== 'regular' || /se$/.test(e.lemma)) return null;
  const c: Conjugation = conjugate(e.lemma, 'regular');
  const table = (c[tk.mood] as Record<string, string[]>)[tk.tense];
  const stem = tk.tense === 'futuro' || tk.tense === 'condicional' ? e.lemma : e.lemma.slice(0, -2);
  const forms = table.map((form, person) => ({ person, form, end: form.slice(stem.length) }));
  if (forms.some((f) => !f.form.startsWith(stem) || !f.end)) return null;
  return { verb: e.lemma, stem, forms, cls: e.lemma.slice(-2) };
}

const piece = (text: string, family: number, role: Piece['role'], k: number): Piece => ({ id: `${role}-${k}-${text}`, text, family, role });

export function makePage(mode: ModeId, words: WordEntry[], seed: number, n = 6): Page | null {
  const r = rng(seed);
  const cfg = MODES.find((m) => m.id === mode)!;
  if (mode === 'silabas') {
    const all = syllableWords(words, cfg.maxLevel);
    const byCons = new Map<string, typeof all>();
    for (const w of all) { const c = consonant(w.s[0]); byCons.set(c, [...(byCons.get(c) ?? []), w]); }
    const fams = shuffle([...byCons.keys()].filter((c) => byCons.get(c)!.length >= 2), r).slice(0, 3);
    if (fams.length < 2) return null;
    const targets: Target[] = [];
    for (let k = 0; targets.length < n && k < 20; k++) {
      const fam = fams[k % fams.length];
      const w = shuffle(byCons.get(fam)!, r).find((x) => !targets.some((t) => t.word === x.e.lemma));
      if (w) targets.push({ word: w.e.lemma, start: w.s[0], end: w.s[1], family: fams.indexOf(fam), hint: w.e.translations });
    }
    const startTexts = [...new Set(targets.map((t) => t.start))];
    const endTexts = [...new Set(targets.map((t) => t.end))];
    const valid = new Map(all.map((w) => [w.e.lemma, `${w.s[0]}|${w.s[1]}`]));
    return {
      mode, targets, families: fams.map((f) => `${f}-`), valid,
      starts: shuffle(startTexts, r).map((s, k) => piece(s, fams.indexOf(consonant(s)), 'start', k)),
      // Endings are not a family here: they stay neutral.
      ends: shuffle(endTexts, r).map((s, k) => piece(s, -1, 'end', k)),
    };
  }
  if (mode === 'sufijos') {
    const all = suffixWords(words, cfg.maxLevel);
    const sufs = shuffle(SUFFIXES.filter((s) => all.filter((w) => w.suffix === s).length >= 3), r).slice(0, 2);
    if (sufs.length < 2) return null;
    const targets: Target[] = [];
    for (const s of sufs) for (const w of shuffle(all.filter((x) => x.suffix === s), r).slice(0, n / 2)) {
      targets.push({ word: w.word, start: w.stem, end: s, family: sufs.indexOf(s), hint: w.suffix === 'mente' ? { en: `${w.e.translations.en} (adverb)`, ru: `${w.e.translations.ru} (наречие)` } : w.e.translations });
    }
    const valid = new Map(all.map((w) => [w.word, `${w.stem}|${w.suffix}`]));
    return {
      mode, targets, families: sufs.map((s) => `-${s}`), valid,
      starts: shuffle(targets, r).map((t, k) => piece(t.start, t.family, 'start', k)),
      ends: sufs.map((s, k) => piece(s, k, 'end', k)),
    };
  }
  const tk = TENSES[mode]!;
  const verbs = shuffle(words.filter((e) => levelRank(e.level) <= Math.max(1, levelRank(cfg.maxLevel))), r).map((e) => verbForms(e, tk)).filter((v): v is NonNullable<typeof v> => !!v);
  const chosen: NonNullable<ReturnType<typeof verbForms>>[] = [];
  for (const cls of shuffle(['ar', 'er', 'ir'], r)) { const v = verbs.find((x) => x.cls === cls && !chosen.includes(x)); if (v) chosen.push(v); }
  for (const v of verbs) { if (chosen.length >= 3) break; if (!chosen.includes(v)) chosen.push(v); }
  if (chosen.length < 2) return null;
  const classes = [...new Set(chosen.map((v) => v.cls))];
  const targets: Target[] = [];
  const persons = shuffle([0, 1, 2, 3, 4, 5], r);
  chosen.forEach((v, k) => {
    for (const p of [persons[(2 * k) % 6], persons[(2 * k + 1) % 6], persons[(2 * k + 2) % 6]]) {
      const f = v.forms[p];
      // yo and él share some forms (hablaba): one target per form, two per verb.
      if (targets.filter((t) => t.start === v.stem).length >= 2 || targets.some((t) => t.word === f.form)) continue;
      targets.push({ word: f.form, start: v.stem, end: f.end, family: classes.indexOf(v.cls), hint: `${PERSONS[p]} · ${v.verb}` });
    }
  });
  const valid = new Map<string, string>();
  for (const v of chosen) for (const f of v.forms) valid.set(f.form, `${v.stem}|${f.end}|${PERSONS[f.person]}`);
  const endTexts = new Map<string, number>();
  for (const t of targets) endTexts.set(t.end, t.family);
  // Two more endings of the same verbs, so the choice is real.
  for (const v of shuffle(chosen, r)) for (const f of shuffle(v.forms, r)) { if (endTexts.size >= targets.length + 2) break; if (!endTexts.has(f.end)) endTexts.set(f.end, classes.indexOf(v.cls)); }
  return {
    mode, targets, families: classes.map((c) => `-${c}`), valid,
    starts: chosen.map((v, k) => piece(v.stem, classes.indexOf(v.cls), 'start', k)),
    ends: shuffle([...endTexts.entries()], r).map(([e, fam], k) => piece(e, fam, 'end', k)),
  };
}

export type JoinResult = { kind: 'target'; target: Target } | { kind: 'extra'; word: string; note?: string } | { kind: 'none'; word: string };
/** Joins two pieces: a target of the page, another real word (or form), or nothing. */
export function join(page: Page, found: Set<string>, start: string, end: string): JoinResult {
  const word = start + end;
  const target = page.targets.find((t) => t.word === word && t.start === start && !found.has(t.word));
  if (target) return { kind: 'target', target };
  const v = page.valid.get(word);
  if (v && v.startsWith(`${start}|`)) return { kind: 'extra', word, note: v.split('|')[2] };
  return { kind: 'none', word };
}
export const pageDone = (page: Page, found: Set<string>): boolean => page.targets.every((t) => found.has(t.word));
